// ============================================================
// CALCULAR PERÍODO QUINCENAL
// Día 1  → reporte de la 2ª quincena del mes ANTERIOR (16 al fin)
// Día 16 → reporte de la 1ª quincena del mes ACTUAL   (1 al 15)
// ============================================================
const now = new Date();
const day = now.getDate();
let inicio, fin;

if (day <= 15) {
  // Corriendo el día 1 → período = 16 al último del mes anterior
  inicio = new Date(now.getFullYear(), now.getMonth() - 1, 16);
  fin    = new Date(now.getFullYear(), now.getMonth(), 0); // último día del mes anterior
} else {
  // Corriendo el día 16 → período = 1 al 15 del mes actual
  inicio = new Date(now.getFullYear(), now.getMonth(), 1);
  fin    = new Date(now.getFullYear(), now.getMonth(), 15);
}

const fmtDate = d => d.toISOString().split('T')[0];
const endOfDay = new Date(fin);
endOfDay.setHours(23, 59, 59, 999);

return [{
  json: {
    periodo_inicio:      fmtDate(inicio),
    periodo_fin:         fmtDate(fin),
    ghl_start_timestamp: inicio.getTime(),
    ghl_end_timestamp:   endOfDay.getTime()
  }
}];

const rows = $input.all();
const leads       = rows.reduce((s, r) => s + (Number(r.json.leads_totales)       || 0), 0);
const enviadas    = rows.reduce((s, r) => s + (Number(r.json.agendas_enviadas)    || 0), 0);
const confirmadas = rows.reduce((s, r) => s + (Number(r.json.agendas_confirmadas) || 0), 0);

const diaPico = rows.reduce((max, r) => {
  const l = Number(r.json.leads_totales) || 0;
  return l > (max?.leads || 0) ? { fecha: r.json.fecha, leads: l } : max;
}, null);

return [{
  json: {
    metricas_calculadas: {
      leads_totales:       leads,
      agendas_enviadas:    enviadas,
      agendas_confirmadas: confirmadas,
      tasa_conversion:     leads     > 0 ? ((enviadas    / leads)    * 100).toFixed(1) : '0.0',
      tasa_confirmacion:   enviadas  > 0 ? ((confirmadas / enviadas) * 100).toFixed(1) : '0.0',
      dia_pico: diaPico
    },
    analisis_diario: rows.map(r => ({
      fecha:                r.json.fecha,
      leads_totales:        Number(r.json.leads_totales)       || 0,
      agendas_enviadas:     Number(r.json.agendas_enviadas)    || 0,
      agendas_confirmadas:  Number(r.json.agendas_confirmadas) || 0
    }))
  }
}];

const rows = $input.all();
if (!rows || rows.length === 0) {
  return [{ json: { sessions: [], sessionCount: 0 } }];
}

const sessions = {};
for (const row of rows) {
  const { session_id, message } = row.json;
  if (!session_id) continue;
  if (!sessions[session_id]) sessions[session_id] = [];
  let msg = message;
  if (typeof msg === 'string') {
    try { msg = JSON.parse(msg); } catch(e) { msg = { type: 'unknown', content: String(message) }; }
  }
  const content = (msg.content || '').slice(0, 400);
  if (content) {
    sessions[session_id].push({
      role:    msg.type === 'ai' ? 'Agente' : 'Lead',
      content
    });
  }
}

const sessionList = Object.entries(sessions)
  .map(([sid, messages]) => ({
    session_id:   sid.slice(-6),
    messages,
    messageCount: messages.length
  }))
  .filter(s => s.messageCount >= 2)
  .slice(0, 30);

return [{ json: { sessions: sessionList, sessionCount: sessionList.length } }];

// Combinar todos los datos para enviar a la IA
const periodo   = $('Calcular Período').first().json;
const metricas  = $('Calcular Totales').first().json;
const sesiones  = $('Agrupar Sesiones').first().json;

// Procesar respuesta GHL (el campo puede variar según versión de API)
const ghlRaw  = $input.first().json;
const eventos = ghlRaw.events || ghlRaw.appointments || ghlRaw.data || [];

const citas = (Array.isArray(eventos) ? eventos : []).map(e => ({
  titulo:    e.title || '',
  fecha:     e.startTime ? new Date(Number(e.startTime)).toISOString().split('T')[0] : '',
  status:    e.appointmentStatus || e.status || '',
  notas:     e.notes || e.note || '',
  contactId: e.contactId || ''
})).filter(c => c.fecha);

// Clasificar status de las citas
const isShowed    = s => ['showed', 'completed'].includes(s);
const isNoShowed  = s => ['no-show', 'noShow', 'no_showed', 'no_show'].includes(s);
const isCancelled = s => ['cancelled', 'canceled'].includes(s);
const isBooked    = s => ['booked', 'confirmed'].includes(s);

const estadoCitas = {
  total:         citas.length,
  showed:        citas.filter(c => isShowed(c.status)).length,
  no_showed:     citas.filter(c => isNoShowed(c.status)).length,
  cancelled:     citas.filter(c => isCancelled(c.status)).length,
  booked:        citas.filter(c => isBooked(c.status)).length,
  notas_internas: citas
    .filter(c => c.notas && c.notas.trim())
    .map(c => ({ fecha: c.fecha, nota: c.notas.slice(0, 400) }))
};

return [{
  json: {
    periodo_inicio:    periodo.periodo_inicio,
    periodo_fin:       periodo.periodo_fin,
    metricas_calculadas: metricas.metricas_calculadas,
    analisis_diario:   metricas.analisis_diario,
    sesiones:          sesiones.sessions,
    sessionCount:      sesiones.sessionCount,
    estadoCitas
  }
}];

