// Parsear la respuesta JSON de la IA
let rawContent = $input.first().json;
let contentStr = '';

if (rawContent.message && rawContent.message.content) {
  contentStr = rawContent.message.content;
} else if (rawContent.choices && rawContent.choices[0]) {
  contentStr = rawContent.choices[0].message?.content || '';
} else if (typeof rawContent === 'string') {
  contentStr = rawContent;
} else {
  contentStr = JSON.stringify(rawContent);
}

// Limpiar posibles bloques de código markdown
contentStr = contentStr.replace(/^```json\s*/m, '').replace(/\s*```$/m, '').trim();

let analysis;
try {
  analysis = JSON.parse(contentStr);
} catch(e) {
  const match = contentStr.match(/\{[\s\S]*\}/);
  if (match) {
    try { analysis = JSON.parse(match[0]); }
    catch(e2) { throw new Error('No se pudo parsear respuesta de IA: ' + contentStr.slice(0, 300)); }
  } else {
    throw new Error('Respuesta de IA inválida: ' + contentStr.slice(0, 300));
  }
}

const datos = $('Preparar Datos para IA').first().json;

return [{
  json: {
    // ⚠️ REEMPLAZAR con el UUID real del cliente en Supabase
    cliente_id:           'REEMPLAZAR-CON-UUID-DEL-CLIENTE',
    periodo_inicio:       datos.periodo_inicio,
    periodo_fin:          datos.periodo_fin,
    resumen_ejecutivo:    analysis.resumen_ejecutivo    || '',
    analisis_embudo:      analysis.analisis_embudo      || '',
    patrones_detectados:  analysis.patrones_detectados  || [],
    brechas:              analysis.brechas              || [],
    recomendaciones:      analysis.recomendaciones      || [],
    analisis_llamadas:    analysis.analisis_llamadas    || {},
    control_tecnico:      analysis.control_tecnico      || {},
    conclusion:           analysis.conclusion           || '',
    metricas_calculadas:  datos.metricas_calculadas,
    analisis_diario:      datos.analisis_diario,
    generado_en:          new Date().toISOString()
  }
}];

